import React, {useState} from 'react';
import api from '../lib/api';
import { useNavigate } from 'react-router-dom';

export default function Login(){
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const nav = useNavigate();

  async function submit(e){
    e.preventDefault();
    setError('');
    try{
      const r = await api.post('/auth/login',{email, password});
      localStorage.setItem('hr_token', r.data.token);
      localStorage.setItem('hr_user', JSON.stringify(r.data.user));
      
      // Redirect based on is_admin
      if (r.data.user.is_admin) {
        nav('/admin/products');
      } else {
        nav('/');
      }
    }catch(err){
      const data = err.response?.data;
      let msg = 'Email atau password salah';
      if (data) {
        if (typeof data.message === 'string') msg = data.message;
        else if (data.message && typeof data.message === 'object') {
          const first = Object.values(data.message).flat?.() || Object.values(data.message);
          msg = Array.isArray(first) ? (first[0] || msg) : String(first || msg);
        } else if (typeof data.error === 'string') msg = data.error;
      }
      setError(msg);
    }
  }

  return (
    <div className="container py-16 max-w-md">
      <h2 className="text-2xl font-semibold">Login</h2>
      <p className="text-gray-600 mb-6">Login untuk melanjutkan belanja atau akses admin</p>
      {error && <div className="text-red-600 mb-3">{error}</div>}
      <form onSubmit={submit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium mb-1">Email</label>
          <input 
            type="email"
            className="input" 
            value={email} 
            onChange={e=>setEmail(e.target.value)} 
            placeholder="email" 
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-1">Password</label>
          <input 
            type="password" 
            className="input" 
            value={password} 
            onChange={e=>setPassword(e.target.value)} 
            placeholder="password" 
            required
          />
        </div>
        <div>
          <button type="submit" className="btn btn-primary w-full">Login</button>
        </div>
      </form>
      <div className="text-center mt-4">
        Belum punya akun? <a href="/register" className="text-primary underline">Daftar Sekarang</a>
      </div>
    </div>
  )
}
